/* =========================================================
   data.js — 결 (GYEOL) 공통 데이터
   - 모든 이미지(Base64)는 이 파일에 상수로 "한 번만" 정의합니다.
   - localStorage에는 이미지 문자열을 저장하지 않고 menuId / menuName만 저장합니다.
   - 아래 이미지는 SVG 플레이스홀더(Base64)입니다. 실제 이미지의 Base64 문자열로 교체하세요.
   - 교체할 수 있는 위치에는 "이미지" 주석이 붙어 있습니다. (검색: Ctrl+F → 이미지)
   - 예) img: 'data:image/jpeg;base64,/9j/4AAQ...'
   ========================================================= */

const KEYS = {
  users: 'gyeol_users',
  session: 'gyeol_session',
  cart: 'gyeol_cart',
  lastOrder: 'gyeol_lastOrder',
  reviews: 'gyeol_reviews',
  orders: 'gyeol_orders',
  branch: 'gyeol_branch'
};

const Store = {
  get(k, d) {
    try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; }
    catch (e) { return d; }
  },
  set(k, v) { localStorage.setItem(k, JSON.stringify(v)); }
};

function esc(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function won(n) { return Number(n).toLocaleString('ko-KR') + '원'; }

/* 플레이스홀더 이미지 생성 (SVG → Base64). 실제 이미지로 교체 시 이 함수 호출부를 Base64 문자열로 바꾸면 됩니다. */
function ph(label, bg, fg, w, h) {
  w = w || 800; h = h || 600;
  const svg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '">' +
    '<rect width="100%" height="100%" fill="' + bg + '"/>' +
    '<circle cx="' + (w * 0.82) + '" cy="' + (h * 0.2) + '" r="' + (h * 0.18) + '" fill="' + fg + '" opacity="0.08"/>' +
    '<circle cx="' + (w * 0.15) + '" cy="' + (h * 0.85) + '" r="' + (h * 0.25) + '" fill="' + fg + '" opacity="0.06"/>' +
    '<text x="50%" y="50%" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif" font-size="' + Math.round(h * 0.075) + '" fill="' + fg + '">' + label + '</text>' +
    '<text x="50%" y="' + (h * 0.62) + '" text-anchor="middle" font-family="sans-serif" font-size="' + Math.round(h * 0.035) + '" letter-spacing="6" fill="' + fg + '" opacity="0.6">GYEOL</text>' +
    '</svg>';
  return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svg)));
}

