/* ---------- 리뷰 저장소 ---------- */
function normReview(r, i) {            // 이전 형식(menuName 단일)으로 저장된 리뷰도 새 형식으로 보정
  if (!r.id) {                       // id 없는 이전 샘플 리뷰는 같은 내용의 Seed와 연결 (중복 방지)
    const sd = SEED_REVIEWS.find(x => x.author === r.author && x.text === r.text);
    r.id = sd ? sd.id : 'old' + i;
  }
  if (!r.menus) r.menus = r.menuName ? [r.menuName] : [];
  if (typeof r.rating !== 'number') r.rating = 5;
  if (!r.branch) r.branch = '';
  return r;
}
function getReviews() {
  let r = Store.get(KEYS.reviews, null);
  if (!r || !r.length) { r = SEED_REVIEWS.slice(); Store.set(KEYS.reviews, r); }
  r = r.map(normReview);
  let changed = false;
  // 샘플 리뷰 중 아직 저장되지 않은 것은 추가 (이전 버전에서 저장된 데이터 보정)
  SEED_REVIEWS.forEach(sd => { if (!r.some(x => x.id === sd.id)) { r.push(Object.assign({}, sd)); changed = true; } });
  // 지점 정보가 없는 리뷰는 임의의 지점을 배정 (이전 버전 샘플 리뷰 포함)
  r.forEach((x, i) => {
    if (!x.branch) { const sd = SEED_REVIEWS.find(y => y.id === x.id); x.branch = sd ? sd.branch : BRANCHES[i % BRANCHES.length].name; changed = true; }
  });
  if (changed) Store.set(KEYS.reviews, r);
  return r;
}
function saveReviews(list) { Store.set(KEYS.reviews, list); }
function fmtRating(n) { return Number(n).toFixed(1); }
function todayStr() {
  const d = new Date();
  return d.getFullYear() + '.' + String(d.getMonth() + 1).padStart(2, '0') + '.' + String(d.getDate()).padStart(2, '0');
}
/* 별 1개(차콜색) + 점수 표기 */
function ratingHtml(n) { return '<span class="rating"><span class="star">★</span>' + fmtRating(n) + '</span>'; }

/* ---------- 주문 내역 (로그인한 회원별) ---------- */
// 주문 구조: { id, userId, branch, date, items: [{menuId, menuName, qty, ...}] }
const Orders = {
  all() {
    const l = Store.get(KEYS.orders, []);
    let ch = false;   // 지점 정보가 없는 이전 주문에는 임의의 지점을 배정
    l.forEach((o, i) => { if (!o.branch) { o.branch = BRANCHES[i % BRANCHES.length].name; ch = true; } });
    if (ch) Store.set(KEYS.orders, l);
    return l;
  },
  mine(userId) { return this.all().filter(o => o.userId === userId); },
  add(userId, items, branch) {
    const list = this.all();
    list.unshift({ id: 'o' + Date.now() + Math.floor(Math.random() * 1000), userId: userId, branch: branch || '', date: todayStr(), items: items });
    Store.set(KEYS.orders, list);
  }
};

/* ---------- 메뉴 옵션 규칙 ---------- */
const ICE_ONLY = ['c5', 'c6', 't1', 't2'];   // 결 시그니처 라떼, 콜드브루, 말차 오트 라떼, 유자 스파클링 → ICE만 가능
const HOT_ONLY = ['c1'];                      // 에스프레소 → HOT만 가능
const SIZES = [
  { key: 'Tall', add: 0 },
  { key: 'Grande', add: 800 },       // Tall 기준 +800원
  { key: 'Venti', add: 1600 }        // Grande 기준 +800원 (= Tall 기준 +1,600원)
];
const SHOT_PRICE = 600;               // 샷 추가
const DECAF_PRICE = 300;              // 디카페인

function allowedTemps(m) {
  if (!m || m.category !== 'drink') return [];
  if (HOT_ONLY.indexOf(m.id) > -1) return ['HOT'];
  if (ICE_ONLY.indexOf(m.id) > -1) return ['ICE'];
  return ['HOT', 'ICE'];
}
function defaultTemp(m) {
  const a = allowedTemps(m);
  if (!a.length) return null;
  return a.indexOf(m.defOpt) > -1 ? m.defOpt : a[0];
}
function isCoffee(m) { return !!m && m.group === 'coffee'; }   // 샷 추가 / 디카페인은 커피만 가능

/* 장바구니 항목 정규화 (이전에 저장된 데이터도 규칙에 맞게 보정) */
function normItem(it) {
  const m = getMenu(it.menuId); if (!m) return null;
  const drink = m.category === 'drink';
  const temps = allowedTemps(m);
  it.option = drink ? (temps.indexOf(it.option) > -1 ? it.option : defaultTemp(m)) : null;
  it.size = drink ? (SIZES.some(s => s.key === it.size) ? it.size : 'Tall') : null;
  it.shot = isCoffee(m) ? !!it.shot : false;
  it.decaf = isCoffee(m) ? !!it.decaf : false;
  return it;
}
function sameItem(a, b) {
  return a.menuId === b.menuId && a.option === b.option && a.size === b.size && !!a.shot === !!b.shot && !!a.decaf === !!b.decaf;
}
function unitPrice(it) {
  const m = getMenu(it.menuId); if (!m) return 0;
  let p = m.price;
  if (m.category === 'drink') {
    const s = SIZES.find(s => s.key === it.size); p += s ? s.add : 0;
    if (isCoffee(m)) { if (it.shot) p += SHOT_PRICE; if (it.decaf) p += DECAF_PRICE; }
  }
  return p;
}

/* ---------- 장바구니 (이미지 문자열 저장 금지: menuId, menuName, category, option, size, shot, decaf, qty만 저장) ---------- */
const Cart = {
  get() { return Store.get(KEYS.cart, []).map(normItem).filter(Boolean); },
  set(items) { Store.set(KEYS.cart, items); },
  count() { return this.get().reduce((s, i) => s + i.qty, 0); },
  add(menuId) {
    const m = getMenu(menuId); if (!m) return;
    const items = this.get();
    const drink = m.category === 'drink';
    const item = { menuId: m.id, menuName: m.name, category: m.category, option: drink ? defaultTemp(m) : null, size: drink ? 'Tall' : null, shot: false, decaf: false, qty: 1 };
    const found = items.find(i => sameItem(i, item));
    if (found) found.qty += 1; else items.push(item);
    this.set(items);
  }
};
